    public static void main(String[] args) throws IOException {
        new PalindromePuzzle();
    }
}

class PalindromePuzzle {
    PalindromePuzzle() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        int size = Integer.parseInt(reader.readLine());
        String line = reader.readLine();
        char[] sequence = line.toCharArray();
        int[] costs = new int[size];
        String[] costStrings = reader.readLine().split(" ");
        for (int i = 0; i < size; i++) {
            costs[i] = Integer.parseInt(costStrings[i]);
        }
        int[] letterCounts = new int[26];
        int pairs = 0;
        for (int i = 0; i < size / 2; i++) {
            if (sequence[i] == sequence[size - i - 1]) {
                letterCounts[sequence[i] - 'a']++;
                pairs++;
            }
        }
        int maxCount = 0;
        boolean dominant = false;
        int dominantLetter = -1;
        for (int i = 0; i < 26; i++) {
            if (letterCounts[i] * 2 > pairs) {
                dominant = true;
                dominantLetter = i;
            }
        }
        if (!dominant) {
            long totalCost = 0;
            for (int i = 0; i < size / 2; i++) {
                if (sequence[i] != sequence[size - i - 1]) {
                    totalCost += costs[i] + costs[size - i - 1];
                } else {
                    totalCost += Math.max(costs[i], costs[size - i - 1]);
                }
            }
            writer.println(totalCost);
        } else {
            int excess = letterCounts[dominantLetter] - (pairs - letterCounts[dominantLetter]);
            ArrayList<Integer> minValues = new ArrayList<>();
            for (int i = 0; i < size / 2; i++) {
                if (sequence[i] != sequence[size - i - 1] && sequence[i] != ('a' + dominantLetter) && sequence[size - i - 1] != ('a' + dominantLetter)) {
                    minValues.add(Math.min(costs[i], costs[size - i - 1]));
                }
            }
            Collections.sort(minValues);
            long totalSum = 0;
            for (int i = 0; i < size / 2; i++) {
                if (sequence[i] == sequence[size - i - 1]) {
                    totalSum += Math.max(costs[i], costs[size - i - 1]);
                } else {
                    totalSum += costs[i] + costs[size - i - 1];
                }
            }
            for (int i = 0; i < excess && i < minValues.size(); i++) {
                totalSum -= minValues.get(i);
            }
            writer.println(totalSum);
        }
        writer.close();
    }
}
